import{_ as t,o as a,c as o,a3 as i}from"./chunks/framework.B5WAEDB7.js";const m=JSON.parse('{"title":"Map","description":"Display entries as markers on a map.","frontmatter":{"title":"Map","description":"Display entries as markers on a map."},"headers":[],"relativePath":"en/ansichten/karte.md","filePath":"en/ansichten/karte.md","lastUpdated":1787319236000}'),r={name:"en/ansichten/karte.md"};function n(s,e,l,p,d,c){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="map" tabindex="-1">Map <a class="header-anchor" href="#map" aria-label="Permalink to &quot;Map&quot;">​</a></h1><p>The <strong>Map</strong> shows entries as markers on a map.</p><p>The interface describes it as <em>Locations at a glance</em>.</p><p><strong>Suited for:</strong> branches, customers, job sites, assets, event venues, field service planning.</p><h2 id="requirement-a-location-field" tabindex="-1">Requirement: a location field <a class="header-anchor" href="#requirement-a-location-field" aria-label="Permalink to &quot;Requirement: a location field&quot;">​</a></h2><p>The position of the markers comes from a field of type <strong>Geolocation</strong> or <strong>Address</strong>.</p><p>The message in the interface only names the first type:</p><blockquote><p><em>To see a Map, your Grid needs a column of type Geolocation. It determines the position of the markers on the map.</em></p></blockquote><p>Both types are actually available to choose.</p><div class="warning custom-block"><p class="custom-block-title">Addresses need coordinates</p><p>An address is initially just text. For it to become a map marker, coordinates have to be determined for it — so-called geocoding.</p><p>This feature depends on your plan: <em>Upgrade to Pro to use map pins and geolocation for addresses.</em></p><p>For fields of type <strong>Geolocation</strong>, this restriction doesn&#39;t apply, since the coordinates are stored directly in the field.</p></div><div class="tip custom-block"><p class="custom-block-title">If geocoding isn&#39;t available</p><p>Create a column of type <strong>Geolocation</strong> in addition to the address, and enter the coordinates in the format <code>50.12,6.543</code>. You can copy these from any map service. A bit of manual work, but not tied to a plan.</p></div><h2 id="create-a-map" tabindex="-1">Create a map <a class="header-anchor" href="#create-a-map" aria-label="Permalink to &quot;Create a map&quot;">​</a></h2><ol><li>Under the Grid, choose <strong>Create view</strong>.</li><li>Choose <strong>Map</strong>.</li><li>Under <strong>Settings</strong>, set the location field.</li></ol><p>The dialog is called <em>Choose a field of type Geolocation</em>, with the note <em>The field determines the position of the markers on the map.</em></p><p>If no matching field exists, ApptiveGrid offers <strong>Create a field</strong>.</p><h2 id="working-with-the-map" tabindex="-1">Working with the map <a class="header-anchor" href="#working-with-the-map" aria-label="Permalink to &quot;Working with the map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Function</th></tr></thead><tbody><tr><td><strong>Marker</strong></td><td>An entry. Clicking opens the details.</td></tr><tr><td><strong>Search here</strong></td><td>Searches within the currently visible map area</td></tr><tr><td><strong>Entries</strong></td><td>List of entries for the map</td></tr></tbody></table><p>If no entries are visible, the view reports <em>No entries on the map</em>.</p><div class="tip custom-block"><p class="custom-block-title">&quot;No entries on the map&quot; has three causes</p><ol><li>The location field is empty on the entries.</li><li>For addresses, geocoding is missing because the plan doesn&#39;t include it.</li><li>A filter on the view is hiding everything.</li></ol><p>Check these in this order. A filter <code>Location</code> <code>is empty</code> in a table view quickly shows how many entries even have a position.</p></div><h2 id="filter" tabindex="-1">Filter <a class="header-anchor" href="#filter" aria-label="Permalink to &quot;Filter&quot;">​</a></h2><p>Filters work as in any view — useful for narrowing the map down to a specific area.</p><div class="tip custom-block"><p class="custom-block-title">Split maps by purpose</p><p>Instead of showing every location on one map, multiple views pay off: &quot;Active customers,&quot; &quot;Open jobs,&quot; &quot;North region.&quot; With many markers, an unfiltered map quickly becomes unreadable.</p></div><p>→ <a href="/en/ansichten/filtern-sortieren-gruppieren">Filtering, Sorting, Grouping</a></p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/ansichten/was-ist-eine-ansicht">What is a View</a></li><li><a href="/en/referenz/spaltentypen">Column type reference</a> — Address and Geolocation in detail</li><li><a href="/en/ansichten/filtern-sortieren-gruppieren">Filtering, Sorting, Grouping</a></li></ul>',25)])])}const u=t(r,[["render",n]]);export{m as __pageData,u as default};
